<SfDialog @bind-Visible="Visibility" AllowPrerender="true">
</SfDialog>
@code {
    private bool Visibility { get; set; } = true;
}

// Get the first button from the dialog
DialogButton firstButton = dialog.GetButton(0);
if (firstButton != null)
{
    // Use the button instance
    Console.WriteLine($"Button text: {firstButton.Content}");
}

// Get all buttons from the dialog
List<DialogButton> allButtons = dialog.GetButtonItems();
if (allButtons != null)
{
    foreach (var button in allButtons)
    {
        Console.WriteLine($"Button: {button.Content}");
    }
}

// Hide the dialog in response to a mouse click event
private async Task OnCloseButtonClick(MouseEventArgs e)
{
    await dialog.HideAsync(e);
}

// Hide the dialog in response to a keyboard event
private async Task OnKeyDown(KeyboardEventArgs e)
{
    if (e.Key == "Escape")
    {
        await dialog.HideAsync(e);
    }
}

// Refresh dialog position after dynamic content change
dialog.Width = "800px";
dialog.Height = "600px";
await dialog.RefreshPositionAsync();

// Show the dialog in normal mode
await dialog.ShowAsync();

// Show the dialog in full screen mode
await dialog.ShowAsync(true);

// Get current dialog dimensions
DialogDimension dimensions = await dialog.GetDimension();
Console.WriteLine($"Width: {dimensions.Width}, Height: {dimensions.Height}");

member.example:
Dialog service must be configured in the Program.cs file for Blazor WASM App, .NET 6 Blazor Server App and 
Startup.cs file for .NET 5 and lower version Blazor Server App.
In Program.cs dialog service can be configured like the below code:

using Syncfusion.Blazor.Popups;
. . .
builder.Services.AddScoped<SfDialogService>();

In Startup.cs dialog service can be configured like the below code:

using Syncfusion.Blazor.Popups;
. . .
public void ConfigureServices(IServiceCollection services) 
{
    . . .
    services.AddScoped<SfDialogService>();
}

Code example to show confirmation dialog:

bool isConfirm = await DialogService.ConfirmAsync("Are you sure you want to permanently delete these items?", "Delete Multiple Items");
string confirmMessage = isConfirm ? "confirmed" : "canceled";
Console.WriteLine($"The user {confirmMessage} the dialog box.");

Code example to show alert dialog:

await DialogService.AlertAsync("Alert Dialog Content");
Console.WriteLine($"The user closed the alert dialog.");

Code example to show prompt dialog:

string promptText = await DialogService.PromptAsync("Enter your name:", "Join Chat Group", new DialogOptions()
{
    PrimaryButtonOptions = new DialogButtonOptions { Content = "Okay" },
    CancelButtonOptions = new DialogButtonOptions { Content = "Cancel" }, 
});
if (promptText == null)
{
    Console.WriteLine($"The user canceled the dialog box.");
}
else
{
    Console.WriteLine($"The User's input is returned as \"{promptText}\".");
}

In the code example below, the child content is configured for the prompt dialog box:

await DialogService.PromptAsync(null, "Enter Your Details", new DialogOptions()
{
    ChildContent = @<SfTextBox Placeholder="Enter Name"></SfTextBox>
});

Creating and configuring a PopupModel.

var popupModel = new PopupModel
{
    TargetType = TargetType.Relative,
    OffsetX = 10,
    OffsetY = 5,
    Position = new PositionDataModel { X = "left", Y = "top" },
    Collision = new CollisionAxis { X = CollisionType.Flip, Y = CollisionType.Fit }
};

Configuring collision handling for both axes.

var collisionAxis = new CollisionAxis
{
    X = CollisionType.Flip,
    Y = CollisionType.Fit
};

Configuring position data with alignment keywords.

var positionData = new PositionDataModel
{
    X = "center",
    Y = "top"
};

// Or with numeric values
var positionDataNumeric = new PositionDataModel
{
    X = "100",
    Y = "50"
};

example.code:
var animationSettings = new TooltipAnimationSettings
{
    Delay = 100,
    Duration = 300,
    Effect = Effect.FadeIn
};

private void OnTooltipBeforeOpen(TooltipEventArgs args)
{
    if (args.Target != null && args.HasText)
    {
        // Custom logic for tooltip positioning
        args.Left = 100;
        args.Top = 50;
    }
}

var animationModel = new AnimationModel
{
    Open = new TooltipAnimationSettings
    {
        Effect = Effect.FadeIn,
        Duration = 300,
        Delay = 0
    },
    Close = new TooltipAnimationSettings
    {
        Effect = Effect.FadeOut,
        Duration = 200,
        Delay = 0
    }
};

member.example:
Opening a tooltip with custom animation on a specific element.

// Open tooltip on a specific button element with fade-in animation
var customAnimation = new TooltipAnimationSettings { Effect = "FadeIn", Duration = 300 };
await tooltipComponent.OpenAsync(buttonElement, customAnimation);

// Open tooltip with default settings
await tooltipComponent.OpenAsync();

Closing a tooltip with custom animation settings.

// Close tooltip with custom fade-out animation
var customCloseAnimation = new TooltipAnimationSettings { Effect = "FadeOut", Duration = 500 };
await tooltipComponent.CloseAsync(customCloseAnimation);

// Close tooltip with default animation
await tooltipComponent.CloseAsync();

Refreshing the tooltip after dynamic content changes.

// After adding new elements dynamically to the page
await AddNewElementsToPage();
await tooltipComponent.RefreshAsync();

// After modifying existing target elements
await UpdateTargetElementAttributes();
await tooltipComponent.RefreshAsync();

Refreshing tooltip position after layout changes.

// Refresh position after window resize
window.addEventListener("resize", async () => {
    await tooltipComponent.RefreshPositionAsync();
});

// Refresh position for a specific target element after animation
await AnimateElement(targetElement);
await tooltipComponent.RefreshPositionAsync(targetElement);

// Refresh position after scrolling or layout changes
await tooltipComponent.RefreshPositionAsync();
